void rabinKarp(string text, string pattern)
{
    int d = 256;
    int q = 101;

    int n = text.length();
    int m = pattern.length();

    int patternHash = 0;
    int textHash = 0;
    int h = 1;

    for (int i = 0; i < m - 1; i++)
    {
        h = (h * d) % q;
    }

    for (int i = 0; i < m; i++)
    {
        patternHash =
            (d * patternHash + pattern[i]) % q;

        textHash =
            (d * textHash + text[i]) % q;
    }

    for (int i = 0; i <= n - m; i++)
    {
        if (patternHash == textHash)
        {
            int j;

            for (j = 0; j < m; j++)
            {
                if (text[i + j] != pattern[j])
                {
                    break;
                }
            }

            if (j == m)
            {
                cout << "Pattern found at index "
                     << i << endl;
            }
        }

        if (i < n - m)
        {
            textHash =
                (d * (textHash - text[i] * h)
                + text[i + m]) % q;

            if (textHash < 0)
            {
                textHash += q;
            }
        }
    }
}

int main()
{
    string text = "GEEKS FOR GEEKS";
    string pattern = "GEEK";

    rabinKarp(text, pattern);

    return 0;
}

