class DSU
{
    vector<int> parent, rank;

public:
    DSU(int n)
    {
        parent.resize(n);
        rank.resize(n, 0);

        for(int i = 0; i < n; i++)
            parent[i] = i;
    }

    int find(int x)
    {
        if(parent[x] != x)
            parent[x] = find(parent[x]);

        return parent[x];
    }

    bool unite(int a, int b)
    {
        a = find(a);
        b = find(b);

        if(a == b)
            return false;

        if(rank[a] < rank[b])
            swap(a, b);

        parent[b] = a;

        if(rank[a] == rank[b])
            rank[a]++;

        return true;
    }
};

int main()
{
    int V = 4;

    vector<vector<int>> edges = {
        {10, 0, 1},
        {6, 0, 2},
        {5, 0, 3},
        {15, 1, 3},
        {4, 2, 3}
    };

    sort(edges.begin(), edges.end());

    DSU dsu(V);

    int totalWeight = 0;

    for(auto edge : edges)
    {
        int weight = edge[0];
        int u = edge[1];
        int v = edge[2];

        if(dsu.unite(u, v))
        {
            totalWeight += weight;
            cout << u << " - " << v
                 << " : " << weight << endl;
        }
    }

    cout << "Total Weight = "
         << totalWeight << endl;
}

