int minKey(vector<int>& key, vector<bool>& mstSet, int V)
{
    int minValue = INT_MAX;
    int minIndex = -1;

    for (int v = 0; v < V; v++)
    {
        if (!mstSet[v] && key[v] < minValue)
        {
            minValue = key[v];
            minIndex = v;
        }
    }

    return minIndex;
}

void primMST(vector<vector<int>>& graph, int V)
{
    vector<int> parent(V);
    vector<int> key(V, INT_MAX);
    vector<bool> mstSet(V, false);

    key[0] = 0;
    parent[0] = -1;

    for (int count = 0; count < V - 1; count++)
    {
        int u = minKey(key, mstSet, V);
        mstSet[u] = true;

        for (int v = 0; v < V; v++)
        {
            if (graph[u][v] != 0 &&
                !mstSet[v] &&
                graph[u][v] < key[v])
            {
                parent[v] = u;
                key[v] = graph[u][v];
            }
        }
    }

    cout << "Edge - Weight" << endl;

    for (int i = 1; i < V; i++)
    {
        cout << parent[i] << " - " << i
             << " : " << graph[i][parent[i]] << endl;
    }
}

int main()
{
    int V = 5;

    vector<vector<int>> graph = {
        {0, 2, 0, 6, 0},
        {2, 0, 3, 8, 5},
        {0, 3, 0, 0, 7},
        {6, 8, 0, 0, 9},
        {0, 5, 7, 9, 0}
    };

    primMST(graph, V);

    return 0;
}

