int shortestPath(vector<vector<int>>& graph)
{
    int V = graph.size();

    vector<int> cost(V, INT_MAX);

    cost[V - 1] = 0;

    for (int i = V - 2; i >= 0; i--)
    {
        for (int j = i + 1; j < V; j++)
        {
            if (graph[i][j] != 0 &&
                cost[j] != INT_MAX)
            {
                cost[i] = min(
                    cost[i],
                    graph[i][j] + cost[j]
                );
            }
        }
    }

    return cost[0];
}

