int n;
vector<vector<int>> dist;
vector<vector<int>> dp;

int tsp(int mask, int pos)
{
    if (mask == (1 << n) - 1)
    {
        return dist[pos][0];
    }

    if (dp[mask][pos] != -1)
    {
        return dp[mask][pos];
    }

    int answer = INT_MAX;

    for (int city = 0; city < n; city++)
    {
        if ((mask & (1 << city)) == 0)
        {
            int newCost =
                dist[pos][city] +
                tsp(mask | (1 << city), city);

            answer = min(answer, newCost);
        }
    }

    return dp[mask][pos] = answer;
}

int main()
{
    dist = {
        {0, 10, 15, 20},
        {10, 0, 35, 25},
        {15, 35, 0, 30},
        {20, 25, 30, 0}
    };

    n = dist.size();

    dp.assign(
        1 << n,
        vector<int>(n, -1)
    );

    cout << "Minimum tour cost: "
         << tsp(1, 0)
         << endl;

    return 0;
}

